def current(p,jid,sid,lane):return graph(p)['journeys'][jid]['matrixContent']['cells'][sid].get(lane,[])
def notes(p,jid):return [n for stage in graph(p)['journeys'][jid]['matrixContent']['cells'].values() for lane in stage.values() for n in lane]
